 "content": "from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    # Find a full straight divider, then relocate the non-background figure
    # against it and mark the figure's far edge with an 8 line.
    divider = None
    for r, row in enumerate(grid):
        if len(set(row)) == 1 and row[0] != bg:
            divider = ('h', r, row[0]); break
    if divider is None:
        for c in range(w):
            vals = {grid[r][c] for r in range(h)}
            if len(vals) == 1 and next(iter(vals)) != bg:
                divider = ('v', c, next(iter(vals))); break
    out = [row[:] for row in grid]
    if divider is None:
        return out
    axis, pos, line_color = divider
    pts = [(r,c) for r in range(h) for c in range(w)
           if grid[r][c] != bg and grid[r][c] != line_color]
    if not pts:
        return out
    rs, cs = [p[0] for p in pts], [p[1] for p in pts]
    if axis == 'h':
        lo, hi = min(rs), max(rs)
        # Place object on the same side of the divider, directly adjacent.
        delta = (pos + 1 - lo) if lo > pos else (pos - 1 - hi)
        for r,c in pts:
            out[r][c] = bg
        moved = [(r+delta,c) for r,c in pts]
        for r,c in moved:
            if 0 <= r < h: out[r][c] = grid[r-delta][c]
        edge = max(r for r,c in moved) + 1 if lo > pos else min(r for r,c in moved) - 1
        if 0 <= edge < h: out[edge] = [8]*w
    else:
        lo, hi = min(cs), max(cs)
        delta = (pos + 1 - lo) if lo > pos else (pos - 1 - hi)
        for r,c in pts:
            out[r][c] = bg
        moved = [(r,c+delta) for r,c in pts]
        for r,c in moved:
            if 0 <= c < w: out[r][c] = grid[r][c-delta]
        edge = max(c for r,c in moved) + 1 if lo > pos else min(c for r,c in moved) - 1
        if 0 <= edge < w:
            for r in range(h): out[r][edge] = 8
    return out
